sp_widget.client_script:
function widgetcontroller($scope, $timeout, $rootScope, $document, $window) {
  var c = this;
  c.loading = false;
  c.tableSearch = '';
  c.filteredList = [];

  c.limit = 15;
  c.page = 0;

  // ==== Month picker: build list of last 6 months ====
  var now = new Date();
  c.availableMonths = [];
  for (var i = 5; i >= 0; i--) {
    var d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    var year = d.getFullYear();
    var month = d.getMonth() + 1; // 1‑12
    var monthLabel = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][month-1];
    c.availableMonths.push({
      value: year + '-' + (month < 10 ? '0' + month : month),
      label: monthLabel + ' ' + String(year).slice(-2)
    });
  }
  // Default to the most recent month (last in array)
  var defaultMonth = c.availableMonths[c.availableMonths.length - 1].value;

  c.filters = {
      selectedMonth: defaultMonth,
      regions: [],
      depot: '',
      segment: ''
  };

  c.zoneName = '';

  // ---- Outside‑click handler: closes all dropdowns ----
  function handleClickOutside(event) {
    var target = event.target;
    if (target.closest('.clm-multiselect-container') || target.closest('.clm-custom-dropdown')) return;
    $timeout(function() {
      c.regionDropdownOpen = false;
      c.dropdownOpen.depot = false;
    });
  }
  $document.on('click', handleClickOutside);
  $scope.$on('$destroy', function() { $document.off('click', handleClickOutside); });

  /* ===================== REGION MULTISELECT ===================== */
  c.regionDropdownOpen = false;
  c.regionSearch = '';
  c.selectedRegions = [];

  c.openRegionDropdown = function() {
      c.regionDropdownOpen = true;
      c.dropdownOpen.depot = false;
  };
  c.closeRegionDropdown = function() {
      $timeout(function() { c.regionDropdownOpen = false; }, 200);
  };

  c.toggleRegion = function(region) {
      var idx = c.selectedRegions.indexOf(region);
      if (idx === -1) {
          c.selectedRegions.push(region);
      } else {
          c.selectedRegions.splice(idx, 1);
      }
      c.filters.regions = c.selectedRegions.slice();
      c.regionSearch = '';
      c.refresh();
  };

  c.selectAllRegions = function() {
      var allRegions = (c.data && c.data.filterOpts && c.data.filterOpts.regions) || [];
      c.selectedRegions = allRegions.slice();
      c.filters.regions = c.selectedRegions.slice();
      c.regionSearch = '';
      c.refresh();
  };

  c.clearAllRegions = function() {
      c.selectedRegions = [];
      c.filters.regions = [];
      c.regionSearch = '';
      c.refresh();
  };

  c.isRegionSelected = function(region) {
      return c.selectedRegions.indexOf(region) !== -1;
  };

  c.getFilteredRegions = function() {
      var all = (c.data && c.data.filterOpts && c.data.filterOpts.regions) || [];
      var term = (c.regionSearch || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(r) { return r.toLowerCase().indexOf(term) !== -1; });
  };

  c.getRegionDisplayText = function() {
      if (!c.selectedRegions || c.selectedRegions.length === 0) return 'All Regions';
      if (c.selectedRegions.length === 1) return c.selectedRegions[0];
      return c.selectedRegions.length + ' regions selected';
  };

  /* ===================== DEPOT CUSTOM DROPDOWN ===================== */
  c.dropdownOpen = { depot: false };
  var OPTS_MAP = { depot: 'depots' };

  c.openDropdown = function(field) {
      c.dropdownOpen[field] = true;
      if (field === 'depot') { c.regionDropdownOpen = false; }
  };
  c.closeDropdown = function(field) {
      $timeout(function() { c.dropdownOpen[field] = false; }, 150);
  };
  c.onFilterInput = function(field) { c.dropdownOpen[field] = true; c.refresh(); };
  c.getFilteredOptions = function(field) {
      var optsKey = OPTS_MAP[field];
      var all = (c.data && c.data.filterOpts && c.data.filterOpts[optsKey]) || [];
      var term = (c.filters[field] || '').toLowerCase();
      if (!term) return all;
      return all.filter(function(opt) { return String(opt).toLowerCase().indexOf(term) !== -1; });
  };
  c.selectOption = function(field, value) {
      c.filters[field] = value; c.dropdownOpen[field] = false; c.refresh();
  };
  c.clearFilter = function(field, $event) {
      if ($event) { $event.preventDefault(); }
      c.filters[field] = ''; c.refresh();
  };

  // ---- Month change ----
  c.onMonthChange = function() {
      c.refresh();
  };

  // ---- Quick filters & KPI ----
  c.quickFilter = 'all';
  c.riskFilter = '';
  c.kpiFilter = '';
  c.largeExposureSortOrder = 'desc';
  c.selectedRegionDrilldown = null;
  c.regionClientFilter = null;

  c.setQuickFilter = function(f) { 
      c.quickFilter = f; 
      c.page = 0; 
      if (f === 'largeExposure') {
          c._top20Codes = null;
          c.largeExposureSortOrder = 'desc';
      }
  };

  c.setKpiFilter = function(filterName) {
      if (c.kpiFilter === filterName) {
          c.kpiFilter = '';
      } else {
          c.kpiFilter = filterName;
          c.page = 0;
          $timeout(function() {
              var el = document.getElementById('clmTableContainer');
              if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
          }, 100);
      }
  };

  c.setRiskKpiFilter = function() {
      if (c.riskFilter === 'High') {
          c.riskFilter = '';
      } else {
          c.riskFilter = 'High';
          c.page = 0;
          $timeout(function() {
              var el = document.getElementById('clmTableContainer');
              if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
          }, 100);
      }
  };

  c.getFilteredBaseData = function() {
      if (!c.data || !c.data.tableData) return [];
      if (!c.regionClientFilter) return c.data.tableData;
      return c.data.tableData.filter(function(r) { return r.region === c.regionClientFilter; });
  };
  c.getBaseTableCount = function() { return c.getFilteredBaseData().length; };
  c.countOverdue = function() { return c.getFilteredBaseData().filter(c.isOverdue).length; };
  c.countReview = function(days) { return c.getFilteredBaseData().filter(function(row) { return c.isReviewWithin(row, days); }).length; };
  c.countHighRisk = function() { return c.getFilteredBaseData().filter(c.isHighRisk).length; };

  c.isOverdue = function(row) {
      var val = (row.overdueBalance !== undefined && row.overdueBalance !== null) ? row.overdueBalance : (row.overdue !== undefined ? row.overdue : row.od90);
      return !!val && Number(val) > 0;
  };

  c.getReviewDays = function(row) {
      if (row.reviewDays !== undefined && row.reviewDays !== null) return Number(row.reviewDays);
      var parsed = parseInt(row.reviewIn, 10);
      return isNaN(parsed) ? null : parsed;
  };

  c.isReviewWithin = function(row, days) {
      var d = c.getReviewDays(row);
      return d !== null && d >= 0 && d <= days;
  };

  c.isHighRisk = function(row) { return row.risk === 'High'; };

  c.getTop20Outstanding = function() {
      var filtered = c.getFilteredBaseData().filter(function(row) {
          if (c.kpiFilter) {
              var statLower = (row.status || '').toLowerCase();
              if (c.kpiFilter === 'Pending' && statLower.indexOf('pend') === -1) return false;
              if (c.kpiFilter === 'Send-back' && statLower.indexOf('send') === -1 && statLower.indexOf('back') === -1) return false;
              if (c.kpiFilter === 'Rejected' && statLower.indexOf('reject') === -1) return false;
          }
          if (c.riskFilter && row.risk !== c.riskFilter) return false;
          if (c.quickFilter !== 'largeExposure') {
              switch (c.quickFilter) {
                  case 'overdue':   if (!c.isOverdue(row)) return false; break;
                  case 'review15':  if (!c.isReviewWithin(row, 15)) return false; break;
                  case 'review30':  if (!c.isReviewWithin(row, 30)) return false; break;
              }
          }
          return true;
      });
      var sortedByHighest = filtered.sort(function(a, b) { return (b.outstanding || 0) - (a.outstanding || 0); });
      return sortedByHighest.slice(0, 20);
  };

  c.isTop20Customer = function(row) {
      if (!c._top20Codes || c._top20CacheBuster !== c.lastCacheBuster) {
          c._top20Codes = {};
          var top20 = c.getTop20Outstanding();
          top20.forEach(function(r) { c._top20Codes[r.code] = true; });
          c._top20CacheBuster = c.lastCacheBuster;
      }
      return !!c._top20Codes[row.code];
  };

  c.lastCacheBuster = 0;

  c.toggleLargeExposureSort = function() {
      c.largeExposureSortOrder = c.largeExposureSortOrder === 'desc' ? 'asc' : 'desc';
      c._top20Codes = null;
      c.lastCacheBuster++;
      if (c.quickFilter === 'largeExposure') c.page = 0;
  };

  c.getLargeExposureIcon = function() {
      return c.largeExposureSortOrder === 'desc' ? 'fa-sort-amount-desc' : 'fa-sort-amount-asc';
  };

  c.quickFilterPredicate = function(row) {
      if (c.regionClientFilter && row.region !== c.regionClientFilter) return false;
      if (c.kpiFilter) {
          var statLower = (row.status || '').toLowerCase();
          if (c.kpiFilter === 'Pending' && statLower.indexOf('pend') === -1) return false;
          if (c.kpiFilter === 'Send-back' && statLower.indexOf('send') === -1 && statLower.indexOf('back') === -1) return false;
          if (c.kpiFilter === 'Rejected' && statLower.indexOf('reject') === -1) return false;
      }
      if (c.riskFilter && row.risk !== c.riskFilter) return false;
      if (c.quickFilter === 'largeExposure') return c.isTop20Customer(row);
      switch (c.quickFilter) {
          case 'overdue':   return c.isOverdue(row);
          case 'review15':  return c.isReviewWithin(row, 15);
          case 'review30':  return c.isReviewWithin(row, 30);
          case 'all': default: return true;
      }
  };

  // ===================== CHART 1: Total Outstanding MoM Trend =====================
  c.trendChart = { points: [], activePoints: [], yTicks: [], linePoints: '', areaPath: '', width: 1200, height: 260, padLeft: 90, padRight: 60, padY: 25, drawHeight: 200, baselineY: 225 };

  c.buildTrendChart = function() {
      var trend = (c.data && c.data.trend && c.data.trend.points) || [];
      if (!trend.length) {
          c.trendChart = { points: [], activePoints: [], yTicks: [], linePoints: '', areaPath: '', width: 1200, height: 260, padLeft: 90, padRight: 60, padY: 25, drawHeight: 200, baselineY: 225 };
          return;
      }
      var width = 1200, height = 260, padLeft = 90, padRight = 60, padY = 25, padBottom = 35;
      var drawHeight = height - padY - padBottom;
      var baselineY = padY + drawHeight;
      var values = trend.map(function(p) { return p.value || 0; });
      var maxVal = Math.max.apply(null, values.concat([0]));
      var minVal = 0;
      if (maxVal <= 0) { maxVal = 1; }
      maxVal = maxVal * 1.1;
      var n = trend.length;
      var stepX = (width - padLeft - padRight) / (n > 1 ? (n - 1) : 1);
      var pts = trend.map(function(p, i) {
          var plotValue = Math.max(0, p.value || 0);
          var x = padLeft + i * stepX;
          var y = padY + (1 - (plotValue - minVal) / (maxVal - minVal)) * drawHeight;
          return { x: x, y: y, label: p.label, value: p.value || 0 };
      });
      var activePts = pts.slice();
      var yTicks = [];
      var tickCount = 4;
      for (var j = 0; j < tickCount; j++) {
          var tickVal = minVal + (maxVal - minVal) * (j / (tickCount - 1));
          var tickY = padY + (1 - (tickVal - minVal) / (maxVal - minVal)) * drawHeight;
          yTicks.push({ y: tickY, label: c.fmtCurrency(tickVal) });
      }
      var linePoints = activePts.map(function(p) { return p.x + ',' + p.y; }).join(' ');
      var areaPath = 'M ' + activePts[0].x + ',' + baselineY + ' ';
      activePts.forEach(function(p) { areaPath += 'L ' + p.x + ',' + p.y + ' '; });
      areaPath += 'L ' + activePts[activePts.length - 1].x + ',' + baselineY + ' Z';
      c.trendChart = {
          points: pts,
          activePoints: activePts,
          yTicks: yTicks,
          linePoints: linePoints,
          areaPath: areaPath,
          width: width,
          height: height,
          padLeft: padLeft,
          padRight: padRight,
          padY: padY,
          drawHeight: drawHeight,
          baselineY: baselineY
      };
  };

  // ===================== CHART.JS SETUP =====================
  var CHART_JS_URL = 'https://cdn.jsdelivr.net/npm/chart.js@2.9.4/dist/Chart.min.js';

  function ensureChartJs(cb) {
      if (typeof Chart !== 'undefined') { cb(); return; }

      if (!window.__clmChartJsPromise) {
          window.__clmChartJsPromise = new Promise(function(resolve, reject) {
              var existing = document.querySelector('script[data-clm-chartjs]');
              if (existing) {
                  existing.addEventListener('load', resolve);
                  existing.addEventListener('error', reject);
                  return;
              }
              var script = document.createElement('script');
              script.src = CHART_JS_URL;
              script.setAttribute('data-clm-chartjs', 'true');
              script.onload = resolve;
              script.onerror = reject;
              document.head.appendChild(script);
          });
      }

      window.__clmChartJsPromise.then(function() {
          $timeout(cb);
      }).catch(function(err) {
          console.error('CLM Widget: failed to load Chart.js from CDN', err);
      });
  }

  window.__clmChartVisibilityTargets = window.__clmChartVisibilityTargets || [];

  function isElementVisible(el) {
      if (!el || !document.body.contains(el)) return false;
      var rect = el.getBoundingClientRect();
      return rect.width > 0 && rect.height > 0;
  }

  function ensureChartVisibilityWatcher() {
      if (window.__clmChartVisibilityWatcher) return;
      window.__clmChartVisibilityWatcher = new MutationObserver(function() {
          window.__clmChartVisibilityTargets.forEach(function(target) {
              var nowVisible = isElementVisible(target.canvas);
              if (nowVisible && !target.wasVisible) {
                  var inst = target.getInstance();
                  if (inst) { inst.resize(); }
              }
              target.wasVisible = nowVisible;
          });
      });
      window.__clmChartVisibilityWatcher.observe(document.body, {
          attributes: true,
          subtree: true,
          attributeFilter: ['class', 'style']
      });
  }

  function registerChartVisibilityTarget(canvas, getChartInstance) {
      if (!canvas) return;
      var already = window.__clmChartVisibilityTargets.some(function(t) { return t.canvas === canvas; });
      if (!already) {
          window.__clmChartVisibilityTargets.push({
              canvas: canvas,
              getInstance: getChartInstance,
              wasVisible: isElementVisible(canvas)
          });
      }
      ensureChartVisibilityWatcher();
  }

  var AGEING_COLORS = [
    { key: '0-30 Days',    color: '#38a169' },
    { key: '31-60 Days',   color: '#f6e05e' },
    { key: '61-90 Days',   color: '#f6ad55' },
    { key: '91-120 Days',  color: '#ed7d31' },
    { key: '121-180 Days', color: '#dd6b20' },
    { key: '>180 Days',    color: '#e53e3e' }
  ];

  var salesChartInstance = null;
  var ageingChartInstance = null;
  c.ageingLegend = [];

  c.renderCharts = function() {
    ensureChartJs(function() {
      renderSalesChart();
      renderAgeingChart();
    });
  };

  function renderSalesChart() {
      var canvas = document.getElementById('portfolioSalesChart');
      if (!canvas || !c.data.salesTrend || !c.data.salesTrend.points || !c.data.salesTrend.points.length) return;

      var labels = c.data.salesTrend.points.map(function(p) { return p.label || ''; });
      var volumes = c.data.salesTrend.points.map(function(p) { return p.volume || 0; });
      var values  = c.data.salesTrend.points.map(function(p) { return p.value || 0; });

      if (salesChartInstance) { 
          try { salesChartInstance.destroy(); } catch(e) {} 
      }

      salesChartInstance = new Chart(canvas.getContext('2d'), {
          type: 'bar',
          data: {
              labels: labels,
              datasets: [
                  {
                      type: 'line',
                      label: 'Credit Sales Value (₹)',
                      data: values,
                      borderColor: '#ed7d31',
                      backgroundColor: '#ed7d31',
                      pointBackgroundColor: '#fff',
                      pointBorderColor: '#ed7d31',
                      pointBorderWidth: 2,
                      pointRadius: 5,
                      borderWidth: 3,
                      lineTension: 0, 
                      fill: false,
                      spanGaps: false, 
                      yAxisID: 'yValue'
                  },
                  {
                      type: 'bar',
                      label: 'Credit Sales Volume (MT)',
                      data: volumes,
                      backgroundColor: '#4472c4',
                      yAxisID: 'yVolume'
                  }
              ]
          },
          options: {
              responsive: true,
              maintainAspectRatio: false,
              legend: { display: false }, 
              scales: {
                  xAxes: [{
                      gridLines: { display: false },
                      ticks: { fontSize: 11, fontColor: '#64748b' }
                  }],
                  yAxes: [
                      {
                          id: 'yVolume',
                          type: 'linear',
                          position: 'left',
                          scaleLabel: { display: true, labelString: 'Credit Sales Volume (MT)', fontColor: '#4a5568', fontStyle: 'bold' },
                          ticks: { fontColor: '#718096' },
                          gridLines: { color: '#e2e8f0' }
                      },
                      {
                          id: 'yValue',
                          type: 'linear',
                          position: 'right',
                          scaleLabel: { display: true, labelString: 'Credit Sales Value (₹)', fontColor: '#4a5568', fontStyle: 'bold' },
                          ticks: { fontColor: '#718096' },
                          gridLines: { drawOnChartArea: false }
                      }
                  ]
              }
          }
      });

      registerChartVisibilityTarget(canvas, function() { return salesChartInstance; });
  }

  function renderAgeingChart() {
      var canvas = document.getElementById('portfolioAgeingChart');
      if (!canvas || !c.data.ageingTrend || !c.data.ageingTrend.months || !c.data.ageingTrend.months.length) return;

      var months = c.data.ageingTrend.months;
      var labels = months.map(function(m) { return m.label || ''; });

      var datasets = AGEING_COLORS.map(function(bucketDef) {
          return {
              label: bucketDef.key,
              backgroundColor: bucketDef.color,
              data: months.map(function(m) {
                  var match = m.buckets.filter(function(b) { return b.label === bucketDef.key; })[0];
                  return match ? (match.value || 0) : 0;
              })
          };
      });

      c.ageingLegend = AGEING_COLORS.map(function(b) { return { label: b.key, color: b.color }; });

      if (ageingChartInstance) { 
          try { ageingChartInstance.destroy(); } catch(e) {} 
      }

      ageingChartInstance = new Chart(canvas.getContext('2d'), {
          type: 'bar',
          data: { labels: labels, datasets: datasets },
          options: {
              responsive: true,
              maintainAspectRatio: false,
              legend: { display: false }, 
              scales: {
                  xAxes: [{ 
                      stacked: true, 
                      gridLines: { display: false },
                      ticks: { fontSize: 11, fontColor: '#64748b' }
                  }],
                  yAxes: [{
                      stacked: true,
                      scaleLabel: { display: true, labelString: 'Outstanding Amount (₹)', fontColor: '#4a5568', fontStyle: 'bold' },
                      ticks: { fontColor: '#718096' },
                      gridLines: { color: '#e2e8f0' }
                  }]
              }
          }
      });

      registerChartVisibilityTarget(canvas, function() { return ageingChartInstance; });
  }

  // Resize handler
  angular.element($window).on('resize', function() {
    if (salesChartInstance) { salesChartInstance.resize(); }
    if (ageingChartInstance) { ageingChartInstance.resize(); }
  });

  // Cleanup on destroy
  $scope.$on('$destroy', function() {
      angular.element($window).off('resize');
      if (salesChartInstance) { try{salesChartInstance.destroy();}catch(e){} }
      if (ageingChartInstance) { try{ageingChartInstance.destroy();}catch(e){} }
  });

  // ===================== REGION RISK HEATMAP =====================
  c.regionRiskData = [];
  c.regionRiskMax = 0;

  c.buildRegionRiskChart = function() {
      var regionMap = {};
      (c.data.tableData || []).forEach(function(row) {
          var r = row.region || 'Unknown';
          if (!regionMap[r]) {
              regionMap[r] = { region: r, totalOutstanding: 0, totalOd90: 0, totalOverdue: 0, customerCount: 0, highRiskCount: 0, mediumRiskCount: 0, lowRiskCount: 0 };
          }
          regionMap[r].totalOutstanding += row.outstanding || 0;
          regionMap[r].totalOd90 += row.od90 || 0;
          regionMap[r].customerCount++;
          if (row.risk === 'High') regionMap[r].highRiskCount++;
          else if (row.risk === 'Medium') regionMap[r].mediumRiskCount++;
          else if (row.risk === 'Low') regionMap[r].lowRiskCount++;
      });
      c.regionRiskData = Object.values(regionMap).sort(function(a, b) { return b.totalOd90 - a.totalOd90; });
      c.regionRiskMax = c.regionRiskData.length > 0 ? c.regionRiskData[0].totalOd90 : 1;
  };

  c.getHeatColor = function(value) {
      if (!value || value === 0) return '#c6f6d5';
      var ratio = Math.min(value / (c.regionRiskMax || 1), 1);
      if (ratio < 0.33) {
          var s = ratio / 0.33;
          return 'rgb(' + Math.round(198 + s * (246 - 198)) + ',' + Math.round(246 + s * (224 - 246)) + ',' + Math.round(213 + s * (94 - 213)) + ')';
      } else if (ratio < 0.66) {
          var s2 = (ratio - 0.33) / 0.33;
          return 'rgb(' + Math.round(246 + s2 * (246 - 246)) + ',' + Math.round(224 + s2 * (173 - 224)) + ',' + Math.round(94 + s2 * (85 - 94)) + ')';
      } else {
          var s3 = (ratio - 0.66) / 0.34;
          return 'rgb(' + Math.round(246 + s3 * (229 - 246)) + ',' + Math.round(173 + s3 * (62 - 173)) + ',' + Math.round(85 + s3 * (62 - 85)) + ')';
      }
  };

  c.getHeatTextColor = function(value) {
      if (!value || value === 0) return '#1f2933';
      var ratio = Math.min(value / (c.regionRiskMax || 1), 1);
      return ratio > 0.55 ? '#fff' : '#1f2933';
  };

  c.drillDownRegion = function(region) {
      if (c.selectedRegionDrilldown === region) {
          c.selectedRegionDrilldown = null;
          c.regionClientFilter = null;
      } else {
          c.selectedRegionDrilldown = region;
          c.regionClientFilter = region;
      }
      c.page = 0;
      $timeout(function() {
          var el = document.getElementById('clmTableContainer');
          if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
      }, 50);
  };

  c.clearDrillDown = function() {
      c.selectedRegionDrilldown = null;
      c.regionClientFilter = null;
      c.page = 0;
  };

  c.regionTooltip = { show: false, x: 0, y: 0, data: null };

  c.showRegionTooltip = function(event, item) {
      c.regionTooltip.data = item;
      var container = event.currentTarget.closest('.clm-heatmap-container');
      if (!container) return;
      var containerRect = container.getBoundingClientRect();
      var targetRect = event.currentTarget.getBoundingClientRect();
      var left = targetRect.right - containerRect.left + 14;
      var top = targetRect.top - containerRect.top;
      if (left + 220 > containerRect.width) left = targetRect.left - containerRect.left - 220;
      if (top + 120 > containerRect.height) top = targetRect.bottom - containerRect.top - 120;
      c.regionTooltip.x = left;
      c.regionTooltip.y = top;
      c.regionTooltip.show = true;
      $scope.$applyAsync();
  };

  c.hideRegionTooltip = function() {
      c.regionTooltip.show = false;
      $scope.$applyAsync();
  };

  c.getActiveFilterCount = function() {
      var count = 0;
      if (c.filters.regions.length > 0) count++;
      if (c.filters.depot) count++;
      if (c.filters.segment) count++;
      if (c.filters.selectedMonth) count++; // month filter counts as active
      if (c.riskFilter) count++;
      if (c.kpiFilter) count++;
      if (c.quickFilter !== 'all') count++;
      if (c.regionClientFilter) count++;
      return count;
  };

  c.filterWrapperClass = '';
  c.clearAllFilters = function() {
      c.filterWrapperClass = 'collapsing';
      $timeout(function() {
          c.filters.regions = [];
          c.selectedRegions = [];
          c.filters.depot = '';
          c.filters.segment = '';
          c.filters.selectedMonth = defaultMonth; // reset to latest month
          c.riskFilter = '';
          c.kpiFilter = '';
          c.quickFilter = 'all';
          c.tableSearch = '';
          c.selectedRegionDrilldown = null;
          c.regionClientFilter = null;
          c.page = 0;
          c._top20Codes = null;
          c.lastCacheBuster++;
          c.filterWrapperClass = '';
          c.refresh();
      }, 350);
  };

  c.refresh = function() {
      c.loading = true;
      c.page = 0;
      c._top20Codes = null;
      c.lastCacheBuster++;

      var payload = { filters: angular.copy(c.filters) };
      // Ensure segment is sent as empty string when 'All Segments' is chosen
      if (!payload.filters.segment) payload.filters.segment = '';

      // Prevent 414 URI too long
      if (c.data && c.data.filterOpts) {
          if (payload.filters.regions && payload.filters.regions.length === (c.data.filterOpts.regions || []).length) {
              payload.filters.regions = [];
          }
      }

      c.server.get(payload).then(function(r) {
          c.data = r.data;
          c.zoneName = c.data.zoneName || '';
          if (c.data.selectedRegions) {
              c.selectedRegions = c.data.selectedRegions;
          }

          if (c.data.tableData && Array.isArray(c.data.tableData)) {
              c.data.tableData.sort(function(a, b) { return (b.outstanding || 0) - (a.outstanding || 0); });
          }
          c.largeExposureSortOrder = 'desc';
          c._top20Codes = null;
          c.lastCacheBuster++;

          c.buildRegionRiskChart();
          c.buildTrendChart();
          c.renderCharts();

          $timeout(function(){ c.loading = false; }, 200);
      });
  };

  c.updatePagination = function() { c.page = 0; };

  c.getPageArray = function() {
      if (!c.filteredList) return [0];
      var totalPages = Math.ceil(c.filteredList.length / c.limit);
      if (totalPages === 0) return [0];
      var maxPage = totalPages - 1;
      var start = Math.max(0, c.page - 2);
      var end = Math.min(maxPage, c.page + 2);
      var arr = [];
      for (var i = start; i <= end; i++) { arr.push(i); }
      return arr;
  };

  c.fmtCurrency = function(value) {
      if (value === undefined || value === null || isNaN(value)) return '—';
      var abs = Math.abs(value);
      var sign = value < 0 ? '-' : '';
      if (abs === 0) return '₹0.0L';
      if (abs >= 1e7) return sign + '₹' + (abs / 1e7).toFixed(1) + ' Cr';
      return sign + '₹' + (abs / 1e5).toFixed(1) + 'L';
  };
  c.fmtRatio = function(value) {
      if (value === undefined || value === null || isNaN(value)) return '—';
      return Number(value).toFixed(2);
  };
  c.fmtDash = function(val) {
      if (!val || isNaN(val) || val === 0) return '—';
      return c.fmtCurrency(val);
  };

  c.capPct = function(pct) {
      if (pct === undefined || pct === null || isNaN(pct)) return 0;
      return Math.max(0, Math.min(100, pct));
  };

  c.selectCustomer = function(row) {
      if (!row || !row.sysId) return;
      $rootScope.clmPendingCustomerSysId = row.sysId;
      $rootScope.clmPendingCustomerCode = row.code;
      $rootScope.$broadcast('clm.customer.selected', { sysId: row.sysId, code: row.code });
      $rootScope.$broadcast('clm.switch.tab', 'customer360');
  };

  // ===================== EXPORT TO CSV LOGIC =====================
  c.exportToCsv = function(chartType) {
      var csvLines = [];
      var fileName = "export.csv";

      if (chartType === 'trend') {
          fileName = "Total_Outstanding_Trend.csv";
          csvLines.push("Month,Total Outstanding (INR)");
          if (c.data.trend && c.data.trend.points) {
              c.data.trend.points.forEach(function(p) {
                  csvLines.push('"' + p.label + '",' + (p.value || 0));
              });
          }
      } else if (chartType === 'sales') {
          fileName = "Sales_Trend.csv";
          csvLines.push("Month,Credit Sales Volume (MT),Credit Sales Value (INR)");
          if (c.data.salesTrend && c.data.salesTrend.points) {
              c.data.salesTrend.points.forEach(function(p) {
                  csvLines.push('"' + p.label + '",' + (p.volume || 0) + "," + (p.value || 0));
              });
          }
      } else if (chartType === 'ageing') {
          fileName = "Ageing_Breakdown.csv";
          csvLines.push("Month,0-30 Days,31-60 Days,61-90 Days,91-120 Days,121-180 Days,>180 Days");
          if (c.data.ageingTrend && c.data.ageingTrend.months) {
              c.data.ageingTrend.months.forEach(function(m) {
                  var row = ['"' + m.label + '"'];
                  var buckets = m.buckets || [];
                  var getVal = function(lbl) {
                      var b = buckets.filter(function(x) { return x.label === lbl; })[0];
                      return b ? b.value : 0;
                  };
                  row.push(getVal('0-30 Days'));
                  row.push(getVal('31-60 Days'));
                  row.push(getVal('61-90 Days'));
                  row.push(getVal('91-120 Days'));
                  row.push(getVal('121-180 Days'));
                  row.push(getVal('>180 Days'));
                  csvLines.push(row.join(","));
              });
          }
      }

      var csvString = csvLines.join("\n");
      var blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
      var link = document.createElement("a");
      var url = URL.createObjectURL(blob);
      link.setAttribute("href", url);
      link.setAttribute("download", fileName);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  c.refresh();
}

sp_widget.css:
.clm-portfolio-overview {
  position: relative;
  font-family: "Helvetica Neue", Arial, sans-serif;
  color: #1f2933;
  padding-bottom: 24px;
}

/* ---------- Smooth Loading Spinner Overlay ---------- */
.clm-loading-overlay {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(255, 255, 255, 0.7);
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: center;
  backdrop-filter: blur(3px);
  border-radius: 8px;
}
.clm-spinner {
  border: 4px solid rgba(49, 130, 206, 0.2);
  border-top: 4px solid #3182ce;
  border-radius: 50%;
  width: 40px;
  height: 40px;
  animation: clm-spin 0.8s linear infinite;
}
@keyframes clm-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

/* ---------- Zone Header ---------- */
.clm-zone-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  margin-bottom: 16px;
  background: linear-gradient(135deg, #1c4e9c 0%, #2b6cb0 100%);
  border-radius: 8px;
  color: #ffffff;
}

.clm-zone-badge {
  background: rgba(255, 255, 255, 0.2);
  padding: 4px 12px;
  border-radius: 12px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 1px;
}

.clm-zone-name {
  font-size: 16px;
  font-weight: 600;
}

/* ---------- Filters ---------- */
.clm-filter-card { margin: 0 0 16px 0; background: #fff; border: 1px solid #e3e6eb; border-radius: 8px; padding: 14px 18px; overflow: visible; }
.clm-filter-row { display: flex; align-items: flex-start; gap: 12px; flex-wrap: nowrap; overflow-x: visible; white-space: nowrap; }
.clm-filter-field { display: flex; align-items: center; gap: 6px; font-size: 13px; color: #5b6470; margin-bottom: 0; font-weight: normal; flex: 1; position: relative; }
.clm-filter-field select {
  width: 100%; min-width: 160px; height: 34px; font-size: 13px; border-radius: 4px;
  border: 1px solid #cbd5e1; background-color: #ffffff; padding: 0 10px; outline: none; cursor: pointer; transition: all 0.2s ease;
}
.clm-filter-field select:hover { border-color: #a0aec0; background-color: #f7fafc; }

/* ---------- Multiselect Region ---------- */
.clm-multiselect-field { position: relative; }
.clm-multiselect-container { position: relative; width: 100%; min-width: 160px; }
.clm-multiselect-trigger {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  height: 34px;
  padding: 0 10px;
  font-size: 13px;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  background: #ffffff;
  cursor: pointer;
  box-sizing: border-box;
  transition: border-color 0.2s;
}
.clm-multiselect-trigger:hover { border-color: #a0aec0; }
.clm-multiselect-container.open .clm-multiselect-trigger { border-color: #1c4e9c; border-bottom-left-radius: 0; border-bottom-right-radius: 0; }
.clm-multiselect-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: #1f2933; flex: 1; }
.clm-multiselect-arrow { color: #a0aec0; font-size: 10px; margin-left: 6px; }
.clm-multiselect-dropdown {
  position: absolute;
  top: 34px; left: 0; right: 0;
  z-index: 60;
  background: #fff;
  border: 1px solid #1c4e9c;
  border-top: none;
  border-bottom-left-radius: 6px;
  border-bottom-right-radius: 6px;
  box-shadow: 0 6px 14px rgba(0,0,0,0.12);
  max-height: 280px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.clm-multiselect-actions {
  display: flex;
  justify-content: space-between;
  padding: 6px 10px;
  border-bottom: 1px solid #e3e6eb;
  background: #f8f9fa;
}
.clm-multiselect-actions a {
  font-size: 11px;
  color: #1c4e9c;
  cursor: pointer;
  font-weight: 600;
}
.clm-multiselect-actions a:hover { text-decoration: underline; }
.clm-multiselect-search {
  width: 100%;
  height: 32px;
  padding: 0 10px;
  border: none;
  border-bottom: 1px solid #e3e6eb;
  font-size: 12px;
  outline: none;
  box-sizing: border-box;
}
.clm-multiselect-list {
  list-style: none;
  margin: 0;
  padding: 4px 0;
  overflow-y: auto;
  max-height: 180px;
}
.clm-multiselect-list li {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 12px;
  font-size: 13px;
  cursor: pointer;
  color: #1f2933;
}
.clm-multiselect-list li:hover { background: #f0f4f9; }
.clm-multiselect-list li.selected { background: #ebf5ff; }
.clm-checkbox {
  width: 14px; height: 14px;
  border: 2px solid #cbd5e1;
  border-radius: 3px;
  display: inline-block;
  flex-shrink: 0;
  position: relative;
}
.clm-checkbox.checked {
  background: #1c4e9c;
  border-color: #1c4e9c;
}
.clm-checkbox.checked::after {
  content: '';
  position: absolute;
  left: 3px; top: 1px;
  width: 4px; height: 7px;
  border: solid #fff;
  border-width: 0 2px 2px 0;
  transform: rotate(45deg);
}

/* ---------- Custom Searchable Dropdown ---------- */
.clm-custom-dropdown { position: relative; }
.clm-dropdown-wrapper { position: relative; width: 100%; min-width: 160px; }
.clm-dropdown-input {
  width: 100%; height: 34px; font-size: 13px; border-radius: 4px; border: 1px solid #cbd5e1;
  background-color: #ffffff; padding: 0 26px 0 10px; outline: none; cursor: pointer; transition: all 0.2s ease; box-sizing: border-box;
}
.clm-dropdown-input:hover { border-color: #a0aec0; background-color: #f7fafc; }
.clm-dropdown-input:focus { border-color: #1c4e9c; background-color: #ffffff; }
.clm-custom-dropdown.open .clm-dropdown-input { border-color: #1c4e9c; border-bottom-left-radius: 0; border-bottom-right-radius: 0; }
.clm-dropdown-clear { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); color: #a0aec0; font-size: 11px; cursor: pointer; }
.clm-dropdown-clear:hover { color: #718096; }
.clm-dropdown-list {
  position: absolute; top: 34px; left: 0; right: 0; z-index: 50; background: #ffffff;
  border: 1px solid #1c4e9c; border-top: 1px solid #e3e6eb; border-bottom-left-radius: 6px; border-bottom-right-radius: 6px;
  box-shadow: 0 6px 14px rgba(0,0,0,0.12); max-height: 220px; overflow-y: auto; list-style: none; margin: 0; padding: 4px 0;
}
.clm-dropdown-list li { padding: 8px 12px; font-size: 13px; color: #1f2933; cursor: pointer; white-space: normal; }
.clm-dropdown-list li:hover { background-color: #f0f4f9; }
.clm-dropdown-list li.active { background-color: #4a5568; color: #ffffff; }
.clm-dropdown-empty { color: #a0aec0 !important; cursor: default !important; font-style: italic; }
.clm-dropdown-empty:hover { background-color: #ffffff !important; }

/* ---------- KPI cards ---------- */
.clm-kpi-grid { display: grid; grid-template-columns: repeat(4, minmax(180px, 1fr)); gap: 14px; margin: 16px 0; }
.clm-kpi-card { 
  position: relative; 
  background: #fff; border: 1px solid #e3e6eb; border-left: 4px solid #c9ced6; 
  border-radius: 6px; padding: 14px 16px; min-height: 100px; 
  box-shadow: 0 1px 2px rgba(0,0,0,0.02); transition: background-color 0.3s, box-shadow 0.3s; 
}
.clm-kpi-card.border-blue   { border-left-color: #1c4e9c; }
.clm-kpi-card.border-orange { border-left-color: #dd6b20; }
.clm-kpi-card.border-green  { border-left-color: #38a169; }
.clm-kpi-card.border-teal   { border-left-color: #319795; }
.clm-kpi-card.border-red    { border-left-color: #e53e3e; }
.clm-kpi-card.border-purple { border-left-color: #7c5cf0; }
.clm-kpi-code { font-size: 10px; font-weight: 700; color: #718096; margin-bottom: 6px; }
.clm-kpi-value { font-size: 24px; font-weight: 700; }
.clm-kpi-value.large { font-size: 28px; }
.clm-kpi-sub { font-size: 11px; color: #8a93a0; margin-top: 2px; }

/* ---- KPI Info Icon Styles ---- */
.clm-kpi-info { 
  position: absolute; 
  top: 10px; 
  right: 10px; 
  color: #2b6cb0; 
  font-size: 15px; 
  transition: all 0.2s ease;
  cursor: pointer;
  z-index: 5;
}
.clm-kpi-info:hover { 
  color: #1c4e9c; 
  transform: scale(1.15); 
}

.text-blue   { color: #2b6cb0; }
.text-orange { color: #dd6b20; }
.text-green  { color: #38a169; }
.text-teal   { color: #319795; }
.text-red    { color: #e53e3e; }
.text-purple { color: #7c5cf0; }
.clm-progress { height: 4px; border-radius: 2px; background: #edf2f7; margin-top: 10px; }
.clm-progress-fill { height: 100%; border-radius: 2px; }
.bg-blue { background: #2b6cb0; }
.bg-teal { background: #319795; }

/* ---------- Charts ---------- */
.clm-chart-card { background: #fff; border: 1px solid #e3e6eb; border-radius: 8px; padding: 16px 20px; margin: 16px 0; overflow: hidden; position: relative; }
.clm-chart-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px; }
.clm-chart-title { font-size: 13px; font-weight: 700; color: #1f2933; }
.clm-chart-badge { font-size: 11px; font-weight: 700; padding: 2px 10px; border-radius: 10px; }
.clm-badge-line { background: #fff7e6; color: #b7791f; }
.clm-badge-combo { background: #e6f0ff; color: #1c4e9c; }
.clm-badge-stacked { background: #f0e6ff; color: #6b21a8; }
.clm-badge-heatmap { background: linear-gradient(135deg, #e53e3e, #dd6b20); color: #fff; padding: 3px 10px; border-radius: 12px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; }

.clm-trend-body { position: relative; height: 260px; padding-top: 10px; width: 100%; }
.clm-trend-svg { width: 100%; height: 260px; display: block; }

.clm-trend-area { fill: rgba(221, 107, 32, 0.1); }
.clm-trend-line { fill: none; stroke: #dd6b20; stroke-width: 2px; }
.clm-trend-dot { fill: #fff; stroke: #dd6b20; stroke-width: 2px; cursor: pointer; transition: r 0.2s; pointer-events: all; }
.clm-trend-dot:hover { r: 6; fill: #dd6b20; }
.clm-trend-dot.last { fill: #dd6b20; }
.clm-trend-grid line { stroke: #e2e8f0; stroke-dasharray: 4; stroke-width: 1px; }
.clm-trend-yaxis text { font-size: 11px; fill: #718096; font-family: "Helvetica Neue", Arial, sans-serif; }
.clm-trend-xaxis text { font-size: 11px; fill: #64748b; font-family: "Helvetica Neue", Arial, sans-serif; }
.clm-chart-empty { text-align: center; color: #a0aec0; padding: 20px; font-style: italic; }

/* ---------- Two-Column Chart Row ---------- */
.clm-charts-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  margin: 16px 0;
}

@media (max-width: 768px) {
  .clm-charts-row { grid-template-columns: 1fr; }
}

.clm-chart-half { margin: 0; overflow: hidden; position: relative; }

.clm-charts-row .clm-chart-wrapper {
  position: relative;
  height: 240px;
  width: 100%;
  padding: 10px 16px;
  box-sizing: border-box;
}
.clm-charts-row .clm-chart-wrapper canvas {
  width: 100% !important;
  height: 100% !important;
}

/* Ageing & Sales Legend */
.clm-ageing-legend {
  display: flex;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
  margin-top: 14px;
  padding: 8px 0 4px 0;
}
.clm-legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  color: #334155;
  font-weight: 600;
}
.clm-legend-color {
  width: 14px;
  height: 14px;
  border-radius: 3px;
  display: inline-block;
}

/* ===================== REGION RISK HEATMAP ===================== */
.clm-heatmap-card { }
.clm-heatmap-container { padding: 16px 20px; }
.clm-heatmap-legend {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 1px solid #e2e8f0;
}
.clm-legend-label { font-size: 12px; font-weight: 600; color: #4a5568; }
.clm-legend-gradient { display: flex; gap: 2px; }
.clm-legend-color { width: 24px; height: 14px; border-radius: 2px; }
.clm-legend-text { font-size: 11px; color: #718096; }

.clm-heatmap-matrix {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-auto-rows: 1fr;
  gap: 2px;
  background: #ffffff;
  border: 0px solid #e2e8f0;
  border-radius: 8px;
  overflow: hidden;
}

.clm-matrix-cell {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 70px;
  cursor: pointer;
  position: relative;
  transition: outline 0.15s ease, outline-offset 0.15s ease;
  background-color: transparent;   
}

.clm-matrix-cell:hover {
  outline: 2px solid #3182ce;
  outline-offset: -2px;
}

.clm-matrix-cell.selected {
  outline: 3px solid #3182ce;
  outline-offset: -3px;
}

.clm-cell-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 8px 4px;
  pointer-events: none;
}

.clm-cell-region { font-size: 14px; font-weight: 700; line-height: 1.2; margin-bottom: 4px; }
.clm-cell-badges { display: flex; gap: 4px; flex-wrap: wrap; justify-content: center; }
.clm-cell-badge {
  padding: 0px 6px;
  border-radius: 10px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.3px;
  background: rgba(255, 255, 255, 0.85);
  border: 1px solid rgba(0,0,0,0.15);
  line-height: 16px;
}

.clm-badge-h { color: #c53030; }
.clm-badge-m { color: #9c4221; }
.clm-badge-l { color: #276749; }

.clm-heatmap-tooltip {
  position: absolute;
  background: rgba(15, 15, 15, 0.95);
  color: #fff;
  padding: 14px 18px;
  border-radius: 10px;
  font-size: 12.5px;
  z-index: 1000;
  pointer-events: none;
  box-shadow: 0 10px 25px rgba(0,0,0,0.35);
  min-width: 200px;
  transition: left 0.1s ease, top 0.1s ease;
  backdrop-filter: blur(4px);
}
.clm-heatmap-tooltip .clm-tooltip-title {
  font-size: 15px;
  font-weight: 700;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid rgba(255,255,255,0.25);
}
.clm-heatmap-tooltip .clm-tooltip-row { margin-bottom: 5px; font-size: 12.5px; line-height: 1.3; }

/* ===================== TABLE SECTION ===================== */
.clm-table-container {
  margin: 16px 0;
  background: #fff;
  border: 1px solid #e3e6eb;
  border-radius: 8px;
  overflow: visible;
  position: relative;
}

.clm-table-wrapper {
  max-height: 450px;
  height: auto;
  overflow-y: auto;
  overflow-x: auto;
  width: 100%;
  -webkit-overflow-scrolling: touch;
}

.clm-table {
  width: 100%;
  border-collapse: collapse;
  table-layout: auto;
}

.clm-table thead th {
  position: sticky;
  top: 0;
  z-index: 10;
  text-align: left;
  padding: 10px 6px;
  background: #f8f9fa;
  color: #718096;
  font-weight: 600;
  text-transform: uppercase;
  font-size: 9px;
  border-bottom: 2px solid #cbd5e1;
  box-shadow: 0 2px 2px -1px rgba(0,0,0,0.1);
  white-space: nowrap;
}

.clm-table td {
  padding: 8px 6px;
  border-bottom: 1px solid #edf2f7;
  color: #1f2933;
  font-size: 11px;
  vertical-align: middle;
  white-space: nowrap;
}

.clm-table td.wrap-text {
  white-space: normal;
  word-break: break-word;
}

.clm-table tbody tr { height: auto; }
.clm-table tbody tr:hover { background-color: #f7fafc; }

/* ===================== CHIPS & QUICK FILTERS ===================== */
.clm-chip-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  padding: 12px 16px;
  background: #fff;
  border-bottom: 1px solid #e3e6eb;
}

.clm-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 600;
  color: #4a5568;
  background: #f8f9fa;
  border: 1px solid #e2e8f0;
  border-radius: 16px;
  cursor: pointer;
  transition: all 0.15s ease;
}
.clm-chip:hover { background: #eef2f7; border-color: #cbd5e1; }
.clm-chip.active { background: #1c4e9c; border-color: #1c4e9c; color: #ffffff; }
.clm-chip .clm-chip-count { background: rgba(0,0,0,0.08); color: inherit; border-radius: 10px; padding: 1px 7px; font-size: 11px; }
.clm-chip.active .clm-chip-count { background: rgba(255,255,255,0.25); }
.clm-chip-warn i   { color: #975a16; }
.clm-chip-orange i { color: #dd6b20; }
.clm-chip-blue i   { color: #1c4e9c; }
.clm-chip-red i    { color: #e53e3e; }
.clm-chip.active i { color: #ffffff; }

.clm-chip-purple {
  background: #f3e8ff;
  color: #7c3aed;
  border: 1px solid #d8b4fe;
}
.clm-chip-purple.active,
.clm-chip-purple:hover {
  background: #7c3aed;
  color: #fff;
  border-color: #7c3aed;
}
.clm-chip-purple.active .clm-chip-count,
.clm-chip-purple:hover .clm-chip-count {
  background: rgba(255,255,255,0.25);
  color: #fff;
}

.clm-selected-region-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  font-size: 12px;
  font-weight: 600;
  color: #fff;
  background: #3182ce;
  border: 1px solid #3182ce;
  border-radius: 16px;
  animation: fadeInChip 0.3s ease;
}
.clm-selected-region-chip i.fa-times {
  cursor: pointer;
  font-size: 11px;
  opacity: 0.8;
  transition: opacity 0.2s;
}
.clm-selected-region-chip i.fa-times:hover { opacity: 1; }

/* Filter transition wrapper */
.clm-filters-transition-wrapper {
  max-height: 200px;
  overflow: hidden;
  transition: max-height 0.35s ease, opacity 0.35s ease, padding 0.35s ease;
  opacity: 1;
  padding: 12px 16px;
  background: #fff;
  border-bottom: 1px solid #e3e6eb;
}
.clm-filters-transition-wrapper.collapsing {
  max-height: 0;
  opacity: 0;
  padding-top: 0;
  padding-bottom: 0;
  border-bottom: none;
}
.clm-active-filters-inline {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  flex: 1;
}
.clm-filter-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #f7fafc;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 2px 10px;
  font-size: 11px;
  font-weight: 600;
  color: #2d3748;
  white-space: nowrap;
  animation: fadeInChip 0.25s ease;
}
@keyframes fadeInChip {
  from { opacity: 0; transform: translateY(-4px); }
  to   { opacity: 1; transform: translateY(0); }
}
.clm-filter-chip i { cursor: pointer; color: #a0aec0; font-size: 10px; transition: color 0.2s; }
.clm-filter-chip i:hover { color: #e53e3e; }
.clm-clear-all-inline {
  background: none;
  border: 1px solid #e2e8f0;
  border-radius: 4px;
  padding: 2px 8px;
  font-size: 11px;
  font-weight: 600;
  color: #e53e3e;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  white-space: nowrap;
  transition: background 0.2s;
}
.clm-clear-all-inline:hover { background: #fff5f5; }

/* ===================== TABLE TOOLBAR & SEARCH ===================== */
.clm-table-toolbar-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 16px;
  background: #fff;
  border-bottom: 1px solid #e3e6eb;
  flex-wrap: wrap;
  gap: 8px;
}
.clm-search-box {
  position: relative;
  display: flex;
  align-items: center;
  flex: 1;
  max-width: 320px;
}
.clm-search-box i { position: absolute; left: 12px; color: #a0aec0; font-size: 13px; }
.clm-search-box input {
  width: 100%;
  height: 34px;
  padding: 0 10px 0 32px;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  font-size: 13px;
  outline: none;
  transition: border 0.2s;
}
.clm-search-box input:focus { border-color: #1c4e9c; }
.clm-table-controls-right {
  display: flex;
  align-items: center;
  font-size: 12px;
  color: #4a5568;
  margin-left: auto;
}
.clm-table-controls-right select {
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  padding: 4px;
  height: 32px;
  outline: none;
  background: #fff;
  cursor: pointer;
  margin-left: 8px;
}
.clm-record-count { font-weight: 600; }
.clm-badge-blue {
  background: #ebf8ff;
  color: #1c4e9c;
  padding: 4px 8px;
  border-radius: 12px;
  font-size: 11px;
  margin-left: 4px;
}

/* ===================== PAGINATION ===================== */
.clm-table-footer {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding: 10px 16px;
  background: #f8f9fa;
  border-top: 1px solid #e3e6eb;
  position: sticky;
  bottom: 0;
  z-index: 10;
}
.clm-page-numbers { display: flex; gap: 4px; }
.clm-page-btn {
  background: #fff;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
  height: 32px;
  min-width: 32px;
  cursor: pointer;
  color: #4a5568;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: center;
}
.clm-page-btn:hover:not(:disabled) { background: #eef2f7; }
.clm-page-btn.active { background: #1c4e9c; color: #fff; border-color: #1c4e9c; }
.clm-page-btn:disabled {
  color: #a0aec0;
  background: #f8f9fa;
  cursor: not-allowed;
  border-color: #e2e8f0;
}

/* ===================== TEXT & UTILITY ===================== */
.clm-nowrap { white-space: nowrap !important; }
.clm-code { color: #2b6cb0; font-weight: 600; cursor: pointer; }
.clm-sub-pan { display: block; font-size: 10px; color: #718096; margin-top: 2px; }

.clm-pill-status {
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 600;
  display: inline-block;
  white-space: nowrap;
}
.status-approved  { background: #e3f4ea; color: #1f7a4d; }
.status-submitted { background: #fffdf0; color: #975a16; }
.status-norequest { background: #f0f4f9; color: #1f2933; }

.seg-cement  { background: #ede9fe; color: #5b21b6; padding: 4px 10px; border-radius: 4px; font-size: 10px; font-weight: 600; display: inline-block; }
.seg-bpd     { background: #fffdf0; color: #975a16; padding: 4px 10px; border-radius: 4px; font-size: 10px; font-weight: 600; display: inline-block; }
.seg-default { background: transparent; color: #1f2933; font-weight: 500; }

.clm-strong { font-weight: 600; }
.clm-text-red { color: #e53e3e !important; font-weight: 600; }
.clm-text-orange { color: #dd6b20 !important; font-weight: 600; }
.clm-text-green { color: #38a169 !important; font-weight: 600; }
.clm-mini-progress { width: 32px; height: 4px; background: #edf2f7; border-radius: 2px; }
.clm-mini-fill { height: 100%; border-radius: 2px; background: currentColor; }

.clm-content-wrap { position: relative; min-height: 200px; }
.clm-content-wrap.clm-loading-active > *:not(.clm-loading-overlay) { opacity: 0.35; filter: blur(1px); pointer-events: none; transition: opacity 0.2s ease; }

/* ===================== YELLOW-ROSE FILTER ACCENTS ===================== */
.clm-filter-field select:hover,
.clm-multiselect-trigger:hover,
.clm-dropdown-input:hover {
  border-color: #e6a04c;
  box-shadow: 0 0 0 1px rgba(230, 160, 76, 0.2);
}

.clm-filter-field select:focus,
.clm-dropdown-input:focus {
  border-color: #e6a04c;
  box-shadow: 0 0 0 2px rgba(230, 160, 76, 0.25);
}

.clm-multiselect-trigger:hover .clm-multiselect-arrow,
.clm-dropdown-clear:hover {
  color: #e6a04c;
}
/* ===================== Export Button Styles ===================== */
.clm-btn-export {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    color: #4a5568;
    border-radius: 4px;
    padding: 4px 10px;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    transition: all 0.2s ease;
    box-shadow: 0 1px 2px rgba(0,0,0,0.02);
}

.clm-btn-export:hover {
    background: #f8f9fa;
    color: #1c4e9c;
    border-color: #a0aec0;
}

.clm-btn-export i {
    font-size: 12px;
}
.clm-multiselect-list li:hover {
  background-color: #fdf3e3;
}

.clm-multiselect-list li.selected {
  background-color: #fce4c2;
}

sp_widget.script:
(function() {
    var TABLES = {
        master:   'x_birl3_clm_clm_customer_master1',
        request:  'x_birl3_clm_clm_new_credit_request',
        snapshot: 'x_birl3_clm_clm_aging_snapshot',
        roleMap:  'x_birl3_clm_role_user_mapping',
        rmcVal:   'x_birl3_clm_clm_cement_rmc_bpd_values',
        salesVol: 'x_birl3_clm_clm_sales_data'
    };

    var inputFilters = (input && input.filters) ? input.filters : {
        selectedMonth: '',   // "YYYY-MM"
        regions: [],
        depot: '',
        segment: ''
    };

    // Normalise regions array
    if (typeof inputFilters.regions === 'string') {
        try { inputFilters.regions = JSON.parse(inputFilters.regions); }
        catch(e) { inputFilters.regions = inputFilters.regions ? [inputFilters.regions] : []; }
    }
    if (!Array.isArray(inputFilters.regions)) {
        inputFilters.regions = inputFilters.regions ? [inputFilters.regions] : [];
    }

    var selectedMonth = inputFilters.selectedMonth || '';
    if (!selectedMonth) {
        // Fallback to current month if nothing selected
        var today = new Date();
        var m = today.getMonth() + 1;
        var y = today.getFullYear();
        selectedMonth = y + '-' + (m < 10 ? '0' + m : m);
    }
    // Parse selected month into start/end dates
    var parts = selectedMonth.split('-');
    var selYear = parseInt(parts[0], 10);
    var selMonth = parseInt(parts[1], 10);
    var startDate = selYear + '-' + (selMonth < 10 ? '0' + selMonth : selMonth) + '-01 00:00:00';
    var lastDay = new Date(selYear, selMonth, 0).getDate(); // month is 1-based, day 0 gives last day of previous month
    var endDate = selYear + '-' + (selMonth < 10 ? '0' + selMonth : selMonth) + '-' + pad2(lastDay) + ' 23:59:59';

    // 6‑month trend window (ending at selectedMonth)
    var trendMonths = [];
    for (var i = 5; i >= 0; i--) {
        var d = new Date(selYear, selMonth - 1 - i, 1); // month 0‑based
        trendMonths.push({ year: d.getFullYear(), month: d.getMonth() + 1 });
    }

    // Helpers
    function extractCode(val) {
        if (!val) return '';
        var match = val.match(/\(([^)]+)\)$/);
        return match ? match[1] : val;
    }
    function extractCodes(arr) {
        if (!arr || !Array.isArray(arr)) return [];
        return arr.map(extractCode).filter(function(c) { return c !== ''; });
    }
    function formatNameCode(name, code) {
        if (name && code && name !== code) return name + ' (' + code + ')';
        return name || code || '';
    }
    function getSafeCode(gr, field) {
        var val = gr.getValue(field) || '';
        if (val.length === 32 && /^[0-9a-f]{32}$/i.test(val)) {
            val = gr.getDisplayValue(field) || '';
        }
        return val;
    }
    function pad2(n) { return n < 10 ? '0' + n : '' + n; }

    var gdtToday = new GlideDateTime();
    var currentUserId = gs.getUserID();
    var MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    var monthNamesLower = ['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'];

    // ============================
    // ROLE‑BASED SEGMENT & ZONE
    // ============================
    var AUTHORIZED_ROLES = {
        'ZHM':    'Cement',
        'ZH_RMC': 'RMC',
        'ZH_BPD': 'BPD',
        'ZCH':    null
    };

    var forcedSegmentLabel = null;
    var userZone = '';
    var userZoneName = '';

    var grRole = new GlideRecord(TABLES.roleMap);
    grRole.addQuery('u_user', currentUserId);
    grRole.addQuery('u_role', 'IN', Object.keys(AUTHORIZED_ROLES));
    grRole.query();

    while (grRole.next()) {
        var roleVal = grRole.getValue('u_role');
        if (roleVal === 'ZCH') {
            forcedSegmentLabel = null;
        } else if (forcedSegmentLabel === null && roleVal !== 'ZCH') {
            var segFromMapping = grRole.getValue('u_segment') || '';
            forcedSegmentLabel = segFromMapping || AUTHORIZED_ROLES[roleVal];
        }
        var zoneVal = grRole.getValue('u_zone') || '';
        if (zoneVal && !userZone) {
            userZone = zoneVal;
            userZoneName = grRole.getValue('zone_name') || userZone;
        }
    }

    if (forcedSegmentLabel === null && !userZone) {
        data.filterOpts = { regions: [], segments: [], depots: [], months: [] };
        data.tableData = [];
        data.kpis = {};
        data.trend = { points: [] };
        data.salesTrend = { points: [] };
        data.ageingTrend = { months: [] };
        return;
    }

    var forcedSegmentRaw = null;
    if (forcedSegmentLabel) {
        var gaSeg = new GlideAggregate(TABLES.master);
        gaSeg.addAggregate('COUNT', 'segment');
        gaSeg.groupBy('segment');
        gaSeg.query();
        while (gaSeg.next()) {
            if (gaSeg.getDisplayValue('segment').toLowerCase() === forcedSegmentLabel.toLowerCase()) {
                forcedSegmentRaw = gaSeg.getValue('segment');
                break;
            }
        }
        if (!forcedSegmentRaw) forcedSegmentRaw = forcedSegmentLabel;
    }

    // ============================
    // FILTER OPTIONS (MONTH LIST NOT USED BY SERVER, BUT BY CLIENT)
    // ============================
    var getDistinctOpts = function(nameField, codeField) {
        var arr = [];
        var ga = new GlideAggregate(TABLES.master);
        if (userZone) ga.addQuery('zone', userZone);

        var parsedRegionCodes = extractCodes(inputFilters.regions);
        var parsedDepotCode = extractCode(inputFilters.depot);

        if (nameField !== 'region_name' && parsedRegionCodes.length > 0) ga.addQuery('region', 'IN', parsedRegionCodes);
        if (nameField !== 'depot_name' && parsedDepotCode) ga.addQuery('depot', parsedDepotCode);

        if (nameField !== 'segment') {
            if (forcedSegmentRaw) ga.addQuery('segment', forcedSegmentRaw);
            else if (inputFilters.segment) ga.addQuery('segment', inputFilters.segment);
        }

        ga.groupBy(nameField);
        if (codeField) ga.groupBy(codeField);
        ga.query();

        while (ga.next()) {
            var nVal = ga.getValue(nameField) || ga.getDisplayValue(nameField) || '';
            var cVal = codeField ? getSafeCode(ga, codeField) : '';
            var displayVal = formatNameCode(nVal, cVal);
            if (displayVal && arr.indexOf(displayVal) === -1) arr.push(displayVal);
        }
        return arr.sort();
    };

    var segmentOptions;
    if (forcedSegmentLabel) {
        segmentOptions = [forcedSegmentLabel];
    } else {
        var segSet = {};
        var gaSegAll = new GlideAggregate(TABLES.master);
        gaSegAll.groupBy('segment');
        gaSegAll.query();
        while (gaSegAll.next()) {
            var segVal = gaSegAll.getDisplayValue('segment') || '';
            if (segVal && !segSet[segVal]) segSet[segVal] = true;
        }
        segmentOptions = Object.keys(segSet).sort();
    }

    data.filterOpts = {
        regions: getDistinctOpts('region_name', 'region'),
        depots: getDistinctOpts('depot_name', 'depot'),
        segments: segmentOptions
    };

    data.zoneName = userZone ? formatNameCode(userZoneName, userZone) : 'All Zones';
    data.selectedRegions = inputFilters.regions;

    // ============================
    // MASTER CUSTOMER LIST
    // ============================
    var masterRecords = [];
    var sysIdArray = [];

    var grCust = new GlideRecord(TABLES.master);
    if (userZone) grCust.addQuery('zone', userZone);

    var activeRegionCodes = extractCodes(inputFilters.regions);
    var activeDepotCode = extractCode(inputFilters.depot);

    if (activeRegionCodes.length > 0) grCust.addQuery('region', 'IN', activeRegionCodes);
    if (activeDepotCode) grCust.addQuery('depot', activeDepotCode);

    if (forcedSegmentRaw) grCust.addQuery('segment', forcedSegmentRaw);
    else if (inputFilters.segment) grCust.addQuery('segment', inputFilters.segment);

    grCust.query();
    while (grCust.next()) {
        var sId = grCust.getUniqueValue();
        sysIdArray.push(sId);
        var rName = grCust.getValue('region_name') || grCust.getDisplayValue('region_name') || '';
        var rCode = getSafeCode(grCust, 'region');
        var dName = grCust.getValue('depot_name') || grCust.getDisplayValue('depot_name') || '';
        var dCode = getSafeCode(grCust, 'depot');
        var zName = grCust.getValue('zone_name') || grCust.getDisplayValue('zone_name') || '';
        var zCode = getSafeCode(grCust, 'zone');

        masterRecords.push({
            sysId: sId,
            code: grCust.getValue('customer_code_sap'),
            name: grCust.getValue('customer_name'),
            pan: grCust.getValue('pan'),
            segment: grCust.getDisplayValue('segment'),
            region: formatNameCode(rName, rCode),
            depot: formatNameCode(dName, dCode),
            zone: formatNameCode(zName, zCode)
        });
    }

    // ============================
    // REQUEST & SNAPSHOT FOR THE SELECTED MONTH
    // ============================
    var reqMap = {};
    var snapMap = {};

    // Requests as of end of selected month
    if (sysIdArray.length > 0) {
        var reqGr = new GlideRecord(TABLES.request);
        reqGr.addQuery('customer', 'IN', sysIdArray);
        reqGr.addQuery('sys_created_on', '<=', endDate);
        reqGr.orderByDesc('sys_created_on');
        reqGr.query();
        while (reqGr.next()) {
            var cId = reqGr.getValue('customer');
            if (!reqMap[cId]) {
                reqMap[cId] = {
                    approvedLimit: parseFloat(reqGr.getValue('approved_limit')) || 0,
                    currentCreditLimit: parseFloat(reqGr.getValue('current_credit_limit')) || 0,
                    outstanding: 0, // we take from snapshot
                    grossExp: parseFloat(reqGr.getValue('net_exposure')) || 0,
                    status: reqGr.getDisplayValue('state') || 'Active',
                    reviewDate: reqGr.getValue('next_review_date'),
                    activeSd: parseFloat(reqGr.getValue('active_sd')) || 0
                };
            }
        }
    }

    // Snapshot for the selected month
    if (sysIdArray.length > 0) {
        var snapGr = new GlideRecord(TABLES.snapshot);
        snapGr.addQuery('customer', 'IN', sysIdArray);
        snapGr.addQuery('snapshot_month', '>=', startDate);
        snapGr.addQuery('snapshot_month', '<=', endDate);
        snapGr.orderBy('snapshot_month'); // only one per customer? ensure one
        snapGr.query();
        while (snapGr.next()) {
            var cId2 = snapGr.getValue('customer');
            if (!snapMap[cId2]) {
                snapMap[cId2] = {
                    totalOutstanding: parseFloat(snapGr.getValue('total_outstanding')) || 0,
                    b0_30: parseFloat(snapGr.getValue('bucket_0_30_days')) || 0,
                    b22_30: parseFloat(snapGr.getValue('bucket_22_30_days')) || 0,
                    b31_45: parseFloat(snapGr.getValue('bucket_31_45_days')) || 0,
                    b46_60: parseFloat(snapGr.getValue('bucket_46_60_days')) || 0,
                    b61_75: parseFloat(snapGr.getValue('bucket_61_75_days')) || 0,
                    b76_90: parseFloat(snapGr.getValue('bucket_76_90_days')) || 0,
                    b91_120: parseFloat(snapGr.getValue('bucket_91_120_days')) || 0,
                    b121_180: parseFloat(snapGr.getValue('bucket_121_180_days')) || 0,
                    b181_365: parseFloat(snapGr.getValue('bucket_181_365_days')) || 0,
                    b366_730: parseFloat(snapGr.getValue('bucket_366_730_days')) || 0,
                    b730_above: parseFloat(snapGr.getValue('bucket_730_above')) || 0,
                    bGt120: parseFloat(snapGr.getValue('bucket_gt120_days')) || 0
                };
            }
        }
    }

    // ============================
    // SALES VALUE & VOLUME FOR THE SELECTED MONTH + 6‑MONTH TREND
    // ============================
    var salesMonthCol = 'u_' + monthNamesLower[selMonth-1] + '_' + String(selYear).slice(-2);
    var volumeMonthCol = salesMonthCol; // same naming convention

    var customerSalesThisMonth = {};   // customer -> sales value for selected month
    var customerVolumeThisMonth = {};

    var salesTrendMap = {};   // YYYY-MM -> total sales value (for 6-month chart)
    var volumeTrendMap = {};
    trendMonths.forEach(function(m) {
        var ym = m.year + '-' + pad2(m.month);
        salesTrendMap[ym] = 0;
        volumeTrendMap[ym] = 0;
    });

    if (sysIdArray.length > 0) {
        // Sales Value table (rmcVal)
        var grSales = new GlideRecord(TABLES.rmcVal);
        grSales.addQuery('u_customer', 'IN', sysIdArray);
        grSales.query();
        while (grSales.next()) {
            var custId = grSales.getValue('u_customer');
            if (!custId) continue;

            // Selected month
            if (grSales.isValidField(salesMonthCol)) {
                var valThisMonth = parseFloat(grSales.getValue(salesMonthCol)) || 0;
                customerSalesThisMonth[custId] = valThisMonth;
            }

            // 6‑month trend
            for (var i = 0; i < trendMonths.length; i++) {
                var tm = trendMonths[i];
                var col = 'u_' + monthNamesLower[tm.month-1] + '_' + String(tm.year).slice(-2);
                if (grSales.isValidField(col)) {
                    var amt = parseFloat(grSales.getValue(col)) || 0;
                    var ymKey = tm.year + '-' + pad2(tm.month);
                    salesTrendMap[ymKey] += amt;
                }
            }
        }

        // Sales Volume table
        var grVol = new GlideRecord(TABLES.salesVol);
        grVol.addQuery('u_customer', 'IN', sysIdArray);
        grVol.query();
        while (grVol.next()) {
            var custIdVol = grVol.getValue('u_customer');
            if (!custIdVol) continue;

            if (grVol.isValidField(volumeMonthCol)) {
                customerVolumeThisMonth[custIdVol] = parseFloat(grVol.getValue(volumeMonthCol)) || 0;
            }

            for (var j = 0; j < trendMonths.length; j++) {
                var tm2 = trendMonths[j];
                var col2 = 'u_' + monthNamesLower[tm2.month-1] + '_' + String(tm2.year).slice(-2);
                if (grVol.isValidField(col2)) {
                    var vol = parseFloat(grVol.getValue(col2)) || 0;
                    var ymKey2 = tm2.year + '-' + pad2(tm2.month);
                    volumeTrendMap[ymKey2] += vol;
                }
            }
        }
    }

    // ============================
    // BUILD TABLE ROWS & KPIs
    // ============================
    var totalApprovedLimit = 0, totalCurrentCreditLimit = 0, totalOutst = 0, totalOverdue = 0, totalOd90 = 0, totalGrossExp = 0, expiringCount = 0;
    var pendingCount = 0, sendBackCount = 0, rejectedCount = 0;
    var totalActiveSd = 0;
    var totalOsSalesRatioSum = 0; // but OS/Sales now per month? we'll compute per customer for the selected month
    var tableData = [];

    for (var k = 0; k < masterRecords.length; k++) {
        var cust = masterRecords[k];
        var req = reqMap[cust.sysId] || {
            approvedLimit: 0, currentCreditLimit: 0, outstanding: 0,
            grossExp: 0, status: 'No Request', reviewDate: '', activeSd: 0
        };
        var snap = snapMap[cust.sysId] || {
            totalOutstanding: 0, b0_30: 0, b22_30: 0, b31_45: 0, b46_60: 0,
            b61_75: 0, b76_90: 0, b91_120: 0, b121_180: 0, b181_365: 0,
            b366_730: 0, b730_above: 0, bGt120: 0
        };

        var custOutstanding = snap.totalOutstanding; // using snapshot outstanding
        var overdue_lt_60 = snap.b0_30 + snap.b22_30 + snap.b31_45 + snap.b46_60;
        var overdue_60_90 = snap.b61_75 + snap.b76_90;
        var overdue_gt_90 = snap.b91_120 + snap.b121_180 + snap.b181_365 + snap.b366_730 + snap.b730_above;
        var rowOverdue = overdue_lt_60 + overdue_60_90 + overdue_gt_90;

        var risk = 'No Overdue';
        var riskClass = '';
        if (overdue_gt_90 > 0) { risk = 'High'; riskClass = 'clm-text-red'; }
        else if (overdue_60_90 > 0) { risk = 'Medium'; riskClass = 'clm-text-orange'; }
        else if (overdue_lt_60 > 0) { risk = 'Low'; riskClass = 'clm-text-green'; }

        var displayStatus = req.status;
        var statLower = (req.status || '').toLowerCase();
        var cssClass = 'status-' + (req.status || 'norequest').toLowerCase().replace(/\s+/g, '-');

        if (statLower.indexOf('submit') > -1) { pendingCount++; displayStatus = 'Pending'; cssClass = 'status-submitted'; }
        if (statLower.indexOf('send') > -1 || statLower.indexOf('back') > -1) sendBackCount++;
        if (statLower.indexOf('reject') > -1) rejectedCount++;
        if (statLower.indexOf('approv') > -1) totalApprovedLimit += req.approvedLimit;

        totalCurrentCreditLimit += req.currentCreditLimit;
        totalOutst += custOutstanding;
        totalGrossExp += req.grossExp;
        totalOverdue += rowOverdue;
        totalOd90 += overdue_gt_90;
        totalActiveSd += req.activeSd || 0;

        var reviewDays = '--', reviewColor = '';
        if (req.reviewDate) {
            var diff = GlideDateTime.subtract(gdtToday, new GlideDateTime(req.reviewDate)).getRoundedDayPart();
            if (diff >= 0 && diff <= 15) expiringCount++;
            reviewDays = diff + 'd';
            if (diff <= 15) reviewColor = 'clm-text-red';
            else if (diff <= 30) reviewColor = 'clm-text-orange';
            else reviewColor = 'clm-text-green';
        }

        var util = req.currentCreditLimit > 0 ? Math.round((custOutstanding / req.currentCreditLimit) * 100) : 0;
        var available = req.currentCreditLimit - custOutstanding;

        // OS/Sales ratio for the selected month
        var custSalesThisMonth = customerSalesThisMonth[cust.sysId] || 0;
        var osSalesRatio = custSalesThisMonth > 0 ? (custOutstanding / custSalesThisMonth) : 0;
        totalOsSalesRatioSum += osSalesRatio;

        tableData.push({
            sysId: cust.sysId,
            code: cust.code,
            name: cust.name,
            pan: cust.pan,
            segment: cust.segment,
            segmentClass: 'seg-' + (cust.segment || 'default').toLowerCase().replace(/\s+/g, '-'),
            region: cust.region,
            depot: cust.depot,
            zone: cust.zone,
            status: displayStatus,
            statusClass: cssClass,
            outstanding: custOutstanding,
            limit: req.currentCreditLimit,
            available: available,
            util: util,
            utilClass: util > 90 ? 'clm-text-red' : (util > 75 ? 'clm-text-orange' : 'clm-text-green'),
            od90: overdue_gt_90,
            risk: risk,
            riskClass: riskClass,
            reviewIn: reviewDays,
            reviewColor: reviewColor,
            osSalesRatio: osSalesRatio
        });
    }

    var totalAvailable = totalCurrentCreditLimit - totalOutst;

    var concentrationRisk = 0;
    if (totalOutst > 0) {
        var hhiSum = 0;
        for (var i = 0; i < tableData.length; i++) {
            var sharePct = (tableData[i].outstanding / totalOutst) * 100;
            hhiSum += sharePct * sharePct;
        }
        concentrationRisk = Math.round(hhiSum);
    }
    var concentrationLabel = 'Less';
    if (concentrationRisk > 2500) concentrationLabel = 'High';
    else if (concentrationRisk >= 1500) concentrationLabel = 'Moderate';

    data.kpis = {
        customerCount: tableData.length,
        limit: totalApprovedLimit,
        outstanding: totalOutst,
        available: totalAvailable,
        utilPct: totalCurrentCreditLimit > 0 ? Math.round((totalOutst / totalCurrentCreditLimit) * 100) : 0,
        osSalesRatio: totalOsSalesRatioSum,
        overdueExposure: totalOverdue,
        od90: totalOd90,
        grossExposure: totalGrossExp,
        expiringCount: expiringCount,
        pendingCount: pendingCount,
        sendBackCount: sendBackCount,
        rejectedCount: rejectedCount,
        concentrationRisk: concentrationRisk,
        concentrationLabel: concentrationLabel,
        netExposure: totalOutst - totalActiveSd
    };
    data.tableData = tableData;

    // ============================
    // 6‑MONTH TREND CHARTS (OUTSTANDING, SALES, AGEING)
    // ============================
    var outstandingPoints = [];
    for (var mi = 0; mi < trendMonths.length; mi++) {
        var tm = trendMonths[mi];
        var ym = tm.year + '-' + pad2(tm.month);
        // We need to aggregate total_outstanding from snapshot for each month in the trend window
        // We'll do this below
    }

    // Aggregate outstanding per month from snapshot table for the trend window
    var outTrendAgg = {};
    if (sysIdArray.length > 0) {
        var snapChunks = [];
        var ids = sysIdArray.slice();
        while (ids.length) snapChunks.push(ids.splice(0, 2000));
        for (var ci = 0; ci < snapChunks.length; ci++) {
            var chunk = snapChunks[ci];
            var gaOut = new GlideAggregate(TABLES.snapshot);
            gaOut.addQuery('customer', 'IN', chunk);
            gaOut.addQuery('snapshot_month', '>=', trendMonths[0].year + '-' + pad2(trendMonths[0].month) + '-01 00:00:00');
            gaOut.addQuery('snapshot_month', '<=', trendMonths[5].year + '-' + pad2(trendMonths[5].month) + '-' + pad2(new Date(trendMonths[5].year, trendMonths[5].month, 0).getDate()) + ' 23:59:59');
            gaOut.addAggregate('SUM', 'total_outstanding');
            gaOut.groupBy('snapshot_month');
            gaOut.query();
            while (gaOut.next()) {
                var sm = gaOut.getValue('snapshot_month');
                if (!sm) continue;
                var yyyy_mm = sm.substring(0, 7);
                outTrendAgg[yyyy_mm] = (outTrendAgg[yyyy_mm] || 0) + (parseFloat(gaOut.getAggregate('SUM', 'total_outstanding')) || 0);
            }
        }
    }

    outstandingPoints = trendMonths.map(function(m) {
        var ym = m.year + '-' + pad2(m.month);
        var label = MONTH_NAMES[m.month-1] + ' ' + String(m.year).slice(-2);
        return { label: label, value: outTrendAgg[ym] || 0 };
    });
    data.trend = { metric: 'outstanding', points: outstandingPoints };

    // Sales & Ageing trend (last 6 months) – already partially computed above, but we need ageing buckets per month
    // Ageing buckets from snapshot aggregated per month
    var snapAggMap = {};
    if (sysIdArray.length > 0) {
        var snapChunks2 = [];
        var ids2 = sysIdArray.slice();
        while (ids2.length) snapChunks2.push(ids2.splice(0, 2000));
        for (var ci2 = 0; ci2 < snapChunks2.length; ci2++) {
            var chunk2 = snapChunks2[ci2];
            var gaSnap = new GlideAggregate(TABLES.snapshot);
            gaSnap.addQuery('customer', 'IN', chunk2);
            gaSnap.addQuery('snapshot_month', '>=', trendMonths[0].year + '-' + pad2(trendMonths[0].month) + '-01 00:00:00');
            gaSnap.addQuery('snapshot_month', '<=', trendMonths[5].year + '-' + pad2(trendMonths[5].month) + '-' + pad2(new Date(trendMonths[5].year, trendMonths[5].month, 0).getDate()) + ' 23:59:59');
            gaSnap.addAggregate('SUM', 'bucket_0_30_days');
            gaSnap.addAggregate('SUM', 'bucket_22_30_days');
            gaSnap.addAggregate('SUM', 'bucket_31_45_days');
            gaSnap.addAggregate('SUM', 'bucket_46_60_days');
            gaSnap.addAggregate('SUM', 'bucket_61_75_days');
            gaSnap.addAggregate('SUM', 'bucket_76_90_days');
            gaSnap.addAggregate('SUM', 'bucket_91_120_days');
            gaSnap.addAggregate('SUM', 'bucket_121_180_days');
            gaSnap.addAggregate('SUM', 'bucket_181_365_days');
            gaSnap.addAggregate('SUM', 'bucket_366_730_days');
            gaSnap.addAggregate('SUM', 'bucket_730_above');
            gaSnap.groupBy('snapshot_month');
            gaSnap.query();
            while (gaSnap.next()) {
                var sm2 = gaSnap.getValue('snapshot_month');
                if (!sm2) continue;
                var y_m = sm2.substring(0, 7);
                if (!snapAggMap[y_m]) {
                    snapAggMap[y_m] = { b0_30:0, b22_30:0, b31_45:0, b46_60:0, b61_75:0, b76_90:0, b91_120:0, b121_180:0, b181_365:0, b366_730:0, b730_above:0 };
                }
                snapAggMap[y_m].b0_30   += parseFloat(gaSnap.getAggregate('SUM','bucket_0_30_days')) || 0;
                snapAggMap[y_m].b22_30  += parseFloat(gaSnap.getAggregate('SUM','bucket_22_30_days')) || 0;
                snapAggMap[y_m].b31_45  += parseFloat(gaSnap.getAggregate('SUM','bucket_31_45_days')) || 0;
                snapAggMap[y_m].b46_60  += parseFloat(gaSnap.getAggregate('SUM','bucket_46_60_days')) || 0;
                snapAggMap[y_m].b61_75  += parseFloat(gaSnap.getAggregate('SUM','bucket_61_75_days')) || 0;
                snapAggMap[y_m].b76_90  += parseFloat(gaSnap.getAggregate('SUM','bucket_76_90_days')) || 0;
                snapAggMap[y_m].b91_120 += parseFloat(gaSnap.getAggregate('SUM','bucket_91_120_days')) || 0;
                snapAggMap[y_m].b121_180+= parseFloat(gaSnap.getAggregate('SUM','bucket_121_180_days')) || 0;
                snapAggMap[y_m].b181_365+= parseFloat(gaSnap.getAggregate('SUM','bucket_181_365_days')) || 0;
                snapAggMap[y_m].b366_730+= parseFloat(gaSnap.getAggregate('SUM','bucket_366_730_days')) || 0;
                snapAggMap[y_m].b730_above+= parseFloat(gaSnap.getAggregate('SUM','bucket_730_above')) || 0;
            }
        }
    }

    var salesPoints = [];
    var ageingData = [];
    for (var ti = 0; ti < trendMonths.length; ti++) {
        var tm = trendMonths[ti];
        var ymKey = tm.year + '-' + pad2(tm.month);
        var lbl = MONTH_NAMES[tm.month-1] + ' ' + String(tm.year).slice(-2);
        salesPoints.push({
            label: lbl,
            value: salesTrendMap[ymKey] || 0,
            volume: volumeTrendMap[ymKey] || 0
        });
        var sData = snapAggMap[ymKey] || { b0_30:0, b22_30:0, b31_45:0, b46_60:0, b61_75:0, b76_90:0, b91_120:0, b121_180:0, b181_365:0, b366_730:0, b730_above:0 };
        ageingData.push({
            label: lbl,
            buckets: [
                { label: '0-30 Days', value: sData.b0_30 + sData.b22_30 },
                { label: '31-60 Days', value: sData.b31_45 + sData.b46_60 },
                { label: '61-90 Days', value: sData.b61_75 + sData.b76_90 },
                { label: '91-120 Days', value: sData.b91_120 },
                { label: '121-180 Days', value: sData.b121_180 },
                { label: '>180 Days', value: sData.b181_365 + sData.b366_730 + sData.b730_above }
            ]
        });
    }
    data.salesTrend = { metric: 'sales', points: salesPoints };
    data.ageingTrend = { months: ageingData };

})();
